  `name` varchar(255) NOT NULL,
  `reason` varchar(255) NOT NULL,
  `amount` varchar(200) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `created_ip` varchar(45) DEFAULT NULL,
